class Solution
{
    struct Info
    {
        bool valid;
        int count;
        long long minimum, maximum;
    };
    int best = 0;
    Info dfs(TreeNode* node)
    {
        if (!node) return {true, 0, LLONG_MAX, LLONG_MIN};
        Info left = dfs(node->left);
        Info right = dfs(node->right);
        if (left.valid && right.valid &&
            left.maximum < node->val && node->val < right.minimum)
            {
            int count = left.count + right.count + 1;
            best = max(best, count);
            return {true, count, min(left.minimum, (long long)node->val),
                    max(right.maximum, (long long)node->val)};
        }
        return {false, 0, 0, 0};
    }
public:
    int largestBSTSubtree(TreeNode* root)
    {
        best = 0;
        dfs(root);
        return best;
    }
};
